from dataclasses import dataclass
from datetime import datetime
from decimal import Decimal


class PromotionExpiredError(Exception):
    def __init__(self, code):
        super().__init__(f"Promotion {code!r} has expired")
        self.code = code


@dataclass(frozen=True)
class Promotion:
    code: str
    percent_off: Decimal
    expires_at: datetime


# PROVISIONAL: product has not decided the expired-promotion behavior.
# Current choice: reject. Change only this function to ignore or confirm instead.
def resolve_promotion(promo, now):
    if promo is None:
        return None
    if now >= promo.expires_at:
        raise PromotionExpiredError(promo.code)
    return promo


def checkout_total(subtotal, promo, now):
    promo = resolve_promotion(promo, now)
    if promo is None:
        return subtotal
    discount = subtotal * promo.percent_off / 100
    return (subtotal - discount).quantize(Decimal("0.01"))
