cat > test_checkout.py <<'E'
import unittest
from datetime import datetime, timedelta
from decimal import Decimal
from checkout import Promotion, PromotionExpiredError, checkout_total

NOW = datetime(2026, 1, 1, 12)
D = Decimal


class CheckoutTests(unittest.TestCase):
    def promo(self, delta):
        return Promotion("SAVE10", D(10), NOW + delta)

    def test_no_promotion(self):
        self.assertEqual(checkout_total(D("50.00"), None, NOW), D("50.00"))

    def test_valid_promotion_applies(self):
        p = self.promo(timedelta(days=1))
        self.assertEqual(checkout_total(D("50.00"), p, NOW), D("45.00"))

    # Provisional: pending product decision on expired promotions.
    def test_expired_promotion_rejected(self):
        p = self.promo(timedelta(days=-1))
        with self.assertRaises(PromotionExpiredError) as c:
            checkout_total(D("50.00"), p, NOW)
        self.assertEqual(c.exception.code, "SAVE10")

    def test_promotion_expiring_exactly_now_is_expired(self):
        with self.assertRaises(PromotionExpiredError):
            checkout_total(D("50.00"), self.promo(timedelta(0)), NOW)


if __name__ == "__main__":
    unittest.main()
